function election(){let ps=tp(team),w=ps.filter(p=>p.willing===true),responded=ps.filter(p=>p.willing!==null).length,fac=ps.find(p=>p.id===team.facilitator_player_id);if(team.status==='majority')return playerPanel(`<h2>TABLE READY · MAJORITY RULE</h2><p>Majority wins. A tied decision goes to the earliest tied vote.</p>`);if(fac)return playerPanel(`<h2>TABLE READY</h2><p>${E(fac.initials)} is the Table Facilitator.</p>`);if(me.willing===null){playerPanel(`<div class="eyebrow">TABLE SETUP</div><h2>Would you help facilitate this table?</h2><button type="button" id="yes">I'M WILLING</button><button type="button" id="no" class="secondary">I'D RATHER PARTICIPATE</button>`);q('#yes').onclick=async()=>{q('#yes').disabled=true;q('#no').disabled=true;await setWilling(true)};q('#no').onclick=async()=>{q('#yes').disabled=true;q('#no').disabled=true;await setWilling(false)};return}if(!w.length&&responded===ps.length){playerPanel(`<h2>No one volunteered.</h2><p>The table can continue with majority rule.</p><button id="majority">USE MAJORITY RULE</button>`);q('#majority').onclick=()=>lock('status','majority','majority');return}if(!w.length)return playerPanel(`<h2>Waiting for responses · ${responded}/${ps.length}</h2>`);if(w.length===1&&responded===ps.length){let only=w[0];playerPanel(`<div class="eyebrow">TABLE FACILITATOR</div><h2>${E(only.initials)} volunteered.</h2><p>${only.id===me.id?'Confirm that you will help the table reach and lock decisions.':'Confirm this table facilitator so the table can continue.'}</p><button type="button" id="confirmFac">CONFIRM TABLE FACILITATOR</button>`);q('#confirmFac').onclick=()=>lock('facilitator_player_id',only.id,'ready');return}let opts=w.map(p=>({id:p.id,label:p.initials}));voteList('facilitator',opts,'Who should facilitate?');if(myVote('facilitator')){let win=winner('facilitator',opts),x=q('.panel');x.insertAdjacentHTML('beforeend',`<button id="lockfac">LOCK ${E(ps.find(p=>p.id===win)?.initials)}</button>`);q('#lockfac').onclick=()=>lock('facilitator_player_id',win,'ready')}}
function voteList(d,opts,title){let mine=myVote(d);playerPanel(`<h2>${E(title)}</h2>${opts.map(o=>`<button class="choice ${mine===o.id?'selected':''}" data-choice="${o.id}" ${o.disabled?'disabled':''}>${E(o.label)}${o.sub?`<span>${E(o.sub)}</span>`:''}</button>`).join('')}`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>cast(d,b.dataset.choice))}
function capVote(){let n=decision(),r=remaining(),used=investments().map(i=>i.capabilityId),mine=myVote('capability'+n),opts=S().capabilities.filter(c=>!used.includes(c.id));playerPanel(`${bars()}<div class="eyebrow">ACTIVATION ${n} OF 2</div><h2>Which capability gives Arthur the strongest transition with the resources available?</h2>${(team.facilitator_player_id===me.id||team.status==='majority')?`<button type="button" class="close-voting" id="closeCapVote">CLOSE VOTING WITH CURRENT RESPONSES</button>`:''}${opts.map(c=>{let[ca,ch]=costs[c.id],d=capabilityLong(c),disabled=ca>r.capital||ch>r.change;return`<article class="phone-cap ${mine===c.id?'selected':''}"><details><summary>${E(c.name)}<span>${ca} Capital · ${ch} Change</span></summary><div class="phone-cap-long"><p><b>FOR ARTHUR</b><br>${E(d.arthur)}</p><p><b>BUILT ENVIRONMENT</b><br>${E(d.environment)}</p><p><b>OPERATING COMMITMENT</b><br>${E(d.operations)}</p><blockquote>${E(d.signal)}</blockquote></div></details><button type="button" data-choice="${c.id}" ${disabled?'disabled':''}>${mine===c.id?'VOTED ✓':'VOTE FOR THIS'}</button></article>`}).join('')}`);document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>castVote('capability'+n,b.dataset.choice,b));if(q('#closeCapVote'))q('#closeCapVote').onclick=()=>closeVoting('capability',n)}
