async function saveInvestment(commitmentId,slot){if(!team||!cap())return;let c=cap(),x=c.choices.find(a=>a.id===commitmentId),[ca,ch]=costs[c.id],items=[...(team.investments||[])],key=`${S().id}:${slot}`,existing=items.findIndex(i=>i.key===key);let item={key,slot:Number(slot),stage:S().id,capabilityId:c.id,name:c.name,capital:ca,change:ch,commitmentId,choice:x};if(existing>=0)items[existing]=item;else if(items.filter(i=>i.stage===S().id).length<2)items.push(item);else return alert('This setting already has two activations.');let capital=7-items.filter(i=>i.stage===S().id).reduce((n,i)=>n+(i.capital||0),0),change=6-items.filter(i=>i.stage===S().id).reduce((n,i)=>n+(i.change||0),0);let buttons=[...document.querySelectorAll('#commitDesign,[data-altcommit],[data-commit]')];buttons.forEach(b=>b.disabled=true);let r=await supabase.from('teams').update({investments:items,capital,change_budget:change,locked_commitment:commitmentId,status:'design locked'}).eq('id',team.id).select('*').single();if(r.error){buttons.forEach(b=>b.disabled=false);return alert(r.error.message)}team=r.data;teams=teams.map(t=>t.id===team.id?team:t);render()}
function resourceCheck(){let r=remaining(),items=investments(),affordable=S().capabilities.filter(c=>!items.some(i=>i.capabilityId===c.id)&&costs[c.id][0]<=r.capital&&costs[c.id][1]<=r.change),can=team.facilitator_player_id===me.id||team.status==='majority'||tp(team).length===1;if(team.status==='proceed_current')return playerPanel(`${bars()}<h2>DESIGN COMPLETE</h2><p>Your table will proceed with the current design.</p>`);if(team.status==='add_support')return playerPanel(`${bars()}<h2>ADDING A SUPPORTING CAPABILITY</h2><p>The room will open Activation 2.</p>`);playerPanel(`${bars()}<h2>IS YOUR DESIGN STRONG ENOUGH?</h2>${items.map(i=>`<div class="summary"><b>${E(i.name)}</b><span>${E(i.choice?.label||'')}</span><small>${i.capital} Capital · ${i.change} Change</small></div>`).join('')}<div class="callout">You may proceed with this design or add one supporting capability if the remaining capacity allows it.</div>${can?`<button type="button" id="proceedCurrent">PROCEED WITH CURRENT DESIGN</button>${affordable.length?'<button type="button" class="secondary" id="addSupport">ADD A SUPPORTING CAPABILITY</button>':'<p><b>No second capability fits the remaining Capital and Change.</b></p>'}`:'<p>The Table Facilitator will decide whether to proceed or add support.</p>'}`);if(q('#proceedCurrent'))q('#proceedCurrent').onclick=()=>setTablePath('proceed_current');if(q('#addSupport'))q('#addSupport').onclick=()=>setTablePath('add_support')}
async function setTablePath(status){let r=await supabase.from('teams').update({status}).eq('id',team.id).select('*').single();if(r.error)return showInlineError(r.error.message);team=r.data;teams=teams.map(t=>t.id===team.id?team:t);render()}
function passive(title,body){playerPanel(`<div class="eyebrow">${E(title)}</div><h2>${E(body)}</h2><p>Follow the room screen.</p>`)}
function playerView(){if(!me||!team)return joinForm(qs.get('room')||'');let p=session.phase;if(['cap_vote2','cap_talk2','commit_vote2','commit_talk2'].includes(p)&&team.status==='proceed_current')return playerPanel(`${bars()}<div class="eyebrow">DESIGN COMPLETE</div><h2>Your table is proceeding with the current design.</h2><p>Follow the room while other tables consider a supporting capability.</p>`);if(p.startsWith('commit_talk')&&!phaseCompleteForTable(team,p)&&!myVote('commitment'+(p.endsWith('2')?'2':'1')))return commitmentVote();if(['resource_check','cap_vote2','designed','event','predict','consequence','principle','complete'].includes(p)&&!investments().length)return team.locked_capability?commitmentVote():capVote();if(p==='elect')return election();if(p==='design_brief')return playerPanel(`<div class="eyebrow">DESIGNING FOR ARTHUR</div><h2>Each capability changes more than technology.</h2><p>Consider the impact on Arthur’s journey, people and operations, and the built environment.</p>`);if(p==='rules')return playerPanel(`<div class="eyebrow">THE ACTIVATION CHALLENGE</div><h2>Design for what comes next. Activate what matters now.</h2><div class="phone-rules"><div><b>7 Capital</b><span>Implementation capacity</span></div><div><b>6 Change</b><span>Organizational capacity</span></div><div><b>Up to 2 activations</b><span>Each must fit both forms of capacity</span></div></div><p>Explore → Vote → Discuss → Commit → Design around it.</p>`);if(p==='journey')return playerPanel(`<div class="eyebrow">ARTHUR’S CARE JOURNEY</div><h2>Leave Well → Recover Well → Live Well</h2><p>Arthur will move from hospital to home, through recovery and back into community life. What the table activates now can shape what follows.</p>`);if(p==='story')return passive('MEET ARTHUR','Arthur is going home today.');if(p==='needs')return playerPanel(`<div class="eyebrow">WHAT ARTHUR NEEDS</div><h2>Leaving well means Arthur needs to:</h2><div class="phone-needs"><div><b>UNDERSTAND</b><span>what happened, what changed and what comes next.</span></div><div><b>MOVE</b><span>safely and confidently from hospital to home.</span></div><div><b>CONNECT</b><span>to medications, people and follow-up that support recovery.</span></div><div><b>TRUST</b><span>that Arthur knows what to do and who will respond as conditions change.</span></div></div><p><b>Your table will design around all four.</b></p>`);if(p==='example')return playerPanel(`<div class="eyebrow">HOW TO READ A CAPABILITY</div><h2>Ambient Discharge + Handoff</h2><p>Tap a capability title during voting to open the long view: Arthur outcome, built-environment implication, operating commitment and cost.</p>`);if(p==='cap_vote1'||p==='cap_vote2')return capVote();if(p==='cap_talk1'||p==='cap_talk2')return capTalk();if(p==='commit_vote1'||p==='commit_vote2')return commitmentVote();if(p==='commit_talk1'||p==='commit_talk2')return commitmentTalk();if(p==='resource_check')return resourceCheck();return passive(p.replaceAll('_',' '),'Follow Arthur’s journey on the room screen.')}
function render(){mode==='facilitator'?facilitatorView():playerView()}

const SOLO_KEY='arthur-by-design-solo-v1';
function defaultSolo(){return{phase:'meet',capital:7,change:6,activations:[],pendingCapability:null,pendingCommitment:null,prediction:null}}
let soloState=null;
function loadSolo(){try{soloState=JSON.parse(localStorage.getItem(SOLO_KEY))||defaultSolo()}catch{soloState=defaultSolo()}}
function saveSolo(){localStorage.setItem(SOLO_KEY,JSON.stringify(soloState))}
function soloGo(phase){soloState.phase=phase;saveSolo();soloRender()}
function soloReset(){localStorage.removeItem(SOLO_KEY);soloState=defaultSolo();saveSolo();soloRender()}
function soloShell(body,{decision=false,conversation=false,complete=false}={}){let cls=decision?'solo-decision':conversation?'solo-conversation':complete?'solo-complete':'';layout(`<div class="solo-utility"><b>SINGLE PLAYER</b><button type="button" id="soloRestart">START OVER</button></div><main class="solo-game ${cls}">${body}</main>`);q('#soloRestart').onclick=()=>{if(confirm('Start Arthur’s journey again?'))soloReset()}}
function soloButton(id,label,fn,secondary=false){setTimeout(()=>{let b=q('#'+id);if(b)b.onclick=fn},0);return`<button type="button" id="${id}" class="${secondary?'secondary':''}">${label}</button>`}
function soloCapability(id){return S().capabilities.find(c=>c.id===id)}
function soloCost(id){return costs[id]||[0,0]}
function soloMeet(){soloShell(`<div class="eyebrow">MEET ARTHUR</div><h1>ARTHUR IS GOING HOME.</h1><p class="solo-lead">Arthur is recovering from cardiac surgery. A successful procedure got Arthur here, but leaving well means more than reaching the hospital exit.</p><p>Arthur must understand a new care plan, move safely through the transition, stay connected to medications and follow-up, and remain confident as conditions change along the way.</p><div class="storyline">THE PROCEDURE IS COMPLETE. ARTHUR’S JOURNEY ISN’T.</div>${soloButton('soloNext','SEE ARTHUR’S JOURNEY',()=>soloGo('journey'))}`)}
function soloJourney(){soloShell(`<div class="eyebrow">ARTHUR’S CARE JOURNEY</div><h1>CARE DOESN’T STOP AT THE HOSPITAL DOOR.</h1><div class="solo-journey"><article class="active"><b>01 · LEAVE WELL</b><span>Hospital → Home</span></article><article><b>02 · RECOVER WELL</b><span>Recovery at Home</span></article><article><b>03 · LIVE WELL</b><span>Back in the Community</span></article></div><p>Arthur moves forward. What is designed and activated in one environment can shape what follows.</p>${soloButton('soloNext','BEGIN LEAVE WELL',()=>soloGo('needs'))}`)}
function soloNeeds(){soloShell(`<div class="eyebrow">LEAVE WELL</div><h1>WHAT WILL HELP ARTHUR LEAVE WELL?</h1><div class="solo-needs"><div><b>UNDERSTAND</b><span>what happened, what changed and what comes next.</span></div><div><b>MOVE</b><span>safely and confidently from hospital to home.</span></div><div><b>CONNECT</b><span>to medications, people and follow-up.</span></div><div><b>TRUST</b><span>that Arthur knows what to do and who will respond.</span></div></div><p><b>Arthur needs all four.</b> The hospital should design for the full journey, while deciding what it can responsibly activate first.</p>${soloButton('soloNext','SEE THE ACTIVATION CHALLENGE',()=>soloGo('rules'))}`)}
function soloRules(){soloShell(`<div class="eyebrow">THE ACTIVATION CHALLENGE</div><h1>DESIGN FOR WHAT COMES NEXT.<br>ACTIVATE WHAT MATTERS NOW.</h1><p>A future-ready environment makes change possible. Making a capability operational still requires implementation and organizational capacity.</p><div class="solo-budget"><div><strong>7</strong><b>CAPITAL</b><span>Fund, build, integrate and enable.</span></div><div><strong>6</strong><b>CHANGE</b><span>Workflow, training, governance and ownership.</span></div></div><p>You may activate up to two capabilities. Each capability must fit both forms of capacity.</p>${soloButton('soloNext','EXPLORE CAPABILITIES',()=>soloGo('capability'))}`)}
function soloBars(){return`<div class="bars"><div><b>CAPITAL</b><span>${'●'.repeat(soloState.capital)}${'○'.repeat(7-soloState.capital)}</span><strong>${soloState.capital}</strong></div><div><b>CHANGE</b><span>${'●'.repeat(soloState.change)}${'○'.repeat(6-soloState.change)}</span><strong>${soloState.change}</strong></div></div>`}
function soloCapabilities(){let used=soloState.activations.map(a=>a.capabilityId),cards=S().capabilities.filter(c=>!used.includes(c.id)).map(c=>{let[ca,ch]=soloCost(c.id),disabled=ca>soloState.capital||ch>soloState.change;return`<article class="solo-card"><details><summary>${E(c.name)}<span>${ca} Capital · ${ch} Change</span></summary><p>${E(c.purpose)}</p><p><b>FOR ARTHUR</b><br>${E(capabilityLong(c)?.arthur||c.purpose)}</p><p><b>BUILT ENVIRONMENT</b><br>${E(capabilityLong(c)?.environment||'The environment must support the care experience.')}</p><p><b>PEOPLE + OPERATIONS</b><br>${E(capabilityLong(c)?.operations||'Workflow and ownership must be explicit.')}</p></details><button type="button" data-solo-cap="${c.id}" ${disabled?'disabled':''}>${disabled?'NOT ENOUGH CAPACITY':'ACTIVATE THIS CAPABILITY'}</button></article>`}).join('');soloShell(`${soloBars()}<div class="eyebrow">YOUR DECISION</div><h1>WHAT WILL YOU ACTIVATE FOR ARTHUR?</h1><p>Explore each option, then activate the capability that gives Arthur the strongest transition with the available capacity.</p><div class="solo-cards">${cards}</div>`,{decision:true});document.querySelectorAll('[data-solo-cap]').forEach(b=>b.onclick=()=>{soloState.pendingCapability=b.dataset.soloCap;saveSolo();soloGo('commitment')})}
function soloCommitment(){let c=soloCapability(soloState.pendingCapability),ctx=commitmentContext(c);soloShell(`<div class="eyebrow">NOW DESIGN AROUND IT</div><h1>${E(c.name)}</h1><div class="solo-arthur"><b>FOR ARTHUR</b><p>${E(capabilityLong(c)?.arthur||c.purpose)}</p></div><h2>${E(ctx.lead)}</h2><p>Explore the strengths and tradeoffs. Then choose the operating model that will make the capability usable for Arthur.</p><div class="solo-cards">${c.choices.map(x=>`<article class="solo-card"><details><summary>${E(x.label)}</summary><p><b>STRENGTH</b><br>${E(x.benefit)}</p><p><b>RISK / TRADEOFF</b><br>${E(x.compromise)}</p></details><button type="button" data-solo-commit="${x.id}">COMMIT TO THIS DESIGN</button></article>`).join('')}</div>`,{decision:true});document.querySelectorAll('[data-solo-commit]').forEach(b=>b.onclick=()=>soloSaveActivation(b.dataset.soloCommit))}
function soloSaveActivation(commitmentId){let c=soloCapability(soloState.pendingCapability),x=c.choices.find(v=>v.id===commitmentId),[ca,ch]=soloCost(c.id);soloState.activations.push({capabilityId:c.id,commitmentId,capital:ca,change:ch,choice:x});soloState.capital-=ca;soloState.change-=ch;soloState.pendingCapability=null;saveSolo();soloGo('design')}
function soloDesign(){let a=soloState.activations.at(-1),c=soloCapability(a.capabilityId),x=a.choice,affordable=S().capabilities.some(k=>!soloState.activations.some(i=>i.capabilityId===k.id)&&soloCost(k.id)[0]<=soloState.capital&&soloCost(k.id)[1]<=soloState.change);soloShell(`${soloBars()}<div class="eyebrow">TABLE COMMITMENT ✓</div><h1>YOUR DESIGN SO FAR</h1><div class="solo-summary"><h2>${E(c.name)}</h2><h3>${E(x.label)}</h3><p><b>ENABLED</b><br>${E(x.benefit)}</p><p><b>ACCEPTED TRADEOFF</b><br>${E(x.compromise)}</p></div><div class="solo-actions">${soloState.activations.length<2&&affordable?soloButton('soloAdd','ADD A SUPPORTING CAPABILITY',()=>soloGo('capability'),true):''}${soloButton('soloProceed','PROCEED WITH CURRENT DESIGN',()=>soloGo('event'))}</div>`,{complete:true})}
function soloEvent(){soloShell(`<div class="eyebrow">CONDITIONS CHANGE</div><h1>ONE ELEVATOR SERVING ARTHUR’S DISCHARGE PATH IS UNAVAILABLE.</h1><p>Nothing failed technically. The environment changed around Arthur.</p><h2>Will your design still help Arthur leave well?</h2><div class="solo-predict"><button data-predict="YES">YES</button><button data-predict="NOT SURE">NOT SURE</button><button data-predict="NO">NO</button></div>`,{decision:true});document.querySelectorAll('[data-predict]').forEach(b=>b.onclick=()=>{soloState.prediction=b.dataset.predict;saveSolo();soloGo('consequence')})}
function soloConsequence(){let a=soloState.activations[0],c=soloCapability(a.capabilityId),x=a.choice;soloShell(`<div class="eyebrow">ARTHUR’S EXPERIENCE</div><h1>${E(x.outcome||'DESIGN TESTED')}</h1><h2>${E(c.name)} · ${E(x.label)}</h2><p class="solo-lead">${E(x.arthur||x.benefit)}</p><div class="solo-result"><div><b>WHAT HELD</b><p>${E(x.held||x.benefit)}</p></div><div><b>${x.outcome==='ABSORBED'?'WHAT YOU TRADED':x.outcome==='STRAINED'?'WHERE IT STRAINED':'WHAT THE DESIGN LEFT EXPOSED'}</b><p>${E(x.outcome==='ABSORBED'?x.compromise:(x.failed||x.compromise))}</p></div></div><blockquote>${E(x.aha||'The capability worked technically. Arthur’s experience depended on the design around it.')}</blockquote>${soloButton('soloNext','WHAT DID WE LEARN?',()=>soloGo('principle'))}`,{complete:true})}
function soloPrinciple(){soloShell(`<div class="eyebrow">FIRMITAS</div><h1>DID THE ARRANGEMENT HOLD WHEN CONDITIONS CHANGED?</h1><p class="solo-lead">AI changed what was possible. Design determined whether Arthur could use it.</p><div class="storyline">ROUND 1 · LEAVE WELL COMPLETE</div><p>Recover Well and Live Well will build from the decisions Arthur carries forward.</p>${soloButton('soloRestartRound','REPLAY LEAVE WELL',()=>soloReset())}`,{complete:true})}
function soloRender(){switch(soloState.phase){case'meet':return soloMeet();case'journey':return soloJourney();case'needs':return soloNeeds();case'rules':return soloRules();case'capability':return soloCapabilities();case'commitment':return soloCommitment();case'design':return soloDesign();case'event':return soloEvent();case'consequence':return soloConsequence();case'principle':return soloPrinciple();default:soloReset()}}
function solo(){loadSolo();soloRender()}

if(mode==='facilitator')facilitator();else if(mode==='player')player();else if(mode==='solo')solo();else start()
